latest.script:
// 搜索接口返回 result.elements[].contents[].duanjuVo。
// 详情接口必须同时带 duanjuId 与 source，所以把 source 追加进 id：
// id = "1013&source=jiuzhou"，详情路由拼进 ?duanjuId={id} 后正好是完整查询串。
function fgJson(raw){ if (typeof raw !== 'string') return raw || {}; try { return JSON.parse(raw); } catch (e) { return {}; } }
function fgItems(json){
  var els = ((json || {}).result || {}).elements || [];
  var out = [], seen = {};
  for (var i = 0; i < els.length; i++) {
    var cs = els[i].contents || [];
    for (var j = 0; j < cs.length; j++) {
      var d = cs[j].duanjuVo;
      if (!d || !d.duanjuId) continue;
      var id = String(d.duanjuId) + '&source=' + (d.source || '');
      if (seen[id]) continue;
      seen[id] = 1;
      out.push({
        id: id,
        title: d.title || '',
        cover: d.coverImageUrl || '',
        description: d.desc || '',
        episodeCount: d.total || 0,
        status: d.updateStatus === 'over' ? '已完结' : '',
        tags: (d.categories || []).join(',')
      });
    }
  }
  return out;
}
function parseList(raw, context){ return fgItems(fgJson(raw)); }

