episodes.script:
// 详情接口的 result.episodeList 已是整本分集；playUrl 是 302 入口（有效期内才可用），
// 分集只存「详情接口地址 + #ep=集ID」，点播时再取一次详情拿当前 playUrl。
function fgJson(raw){ if (typeof raw !== 'string') return raw || {}; try { return JSON.parse(raw); } catch (e) { return {}; } }
function fgBase(ctx){ var b = (ctx && ctx.baseUrl) || ''; return b.charAt(b.length - 1) === '/' ? b.slice(0, -1) : b; }
function parseEpisodes(raw, context){
  var json = fgJson(raw);
  var api = fgBase(context) + '/xifan/drama/getDuanjuInfo?duanjuId=' + ((context && context.id) || '');
  var list = ((json || {}).result || {}).episodeList || [];
  var out = [];
  for (var i = 0; i < list.length; i++) {
    var e = list[i];
    if (!e.episodeId) continue;
    out.push({
      id: String(e.episodeId),
      title: e.title || ('第' + (e.index || (i + 1)) + '集'),
      number: e.index || (i + 1),
      url: api + '#ep=' + encodeURIComponent(e.episodeId)
    });
  }
  return out;
}

video.script:
// playUrl 形如 https://dj.youlishipin.com/duanju/video302?source=&duanjuId=&episodeId=
// 它 302 跳到带签名的 mp4（约 1 小时有效）。返回该 302 入口即可，由播放器自行跟随；
// 若预取拿不到详情（首次进入该集时路由 URL 缺 source），用 __meta 再取一次。
var FG_EP = '';
function fgJson(raw){ if (typeof raw !== 'string') return raw || {}; try { return JSON.parse(raw); } catch (e) { return {}; } }
function fgFind(json, epId){
  var list = ((json || {}).result || {}).episodeList || [];
  for (var i = 0; i < list.length; i++) {
    if (String(list[i].episodeId) === String(epId)) return list[i].playUrl || '';
  }
  return '';
}
function parseVideo(raw, context){
  var url = (context && context.url) || '';
  var cut = url.indexOf('#ep=');
  FG_EP = cut >= 0 ? decodeURIComponent(url.slice(cut + 4)) : '';
  var hit = fgFind(fgJson(raw), FG_EP);
  if (hit) return hit;
  var target = cut >= 0 ? url.slice(0, cut) : url;
  if (target.indexOf('http') === 0) {
    return { __meta: true, __fetchUrl: target, __fetchResponseType: 'json', __processor: 'fgPick' };
  }
  return '';
}
function fgPick(raw){ return fgFind(fgJson(raw), FG_EP); }
